        SELECT 
        FROM `reservation`


                AND (
contact_name LIKE CONCAT('%', #{query.searchKeyword}, '%')
                OR contact_phone LIKE CONCAT('%', #{query.searchKeyword}, '%')
                OR remark LIKE CONCAT('%', #{query.searchKeyword}, '%')
                )

            AND contact_name LIKE CONCAT('%', #{query.contactName}, '%')
            AND contact_phone LIKE CONCAT('%', #{query.contactPhone}, '%')
            AND remark LIKE CONCAT('%', #{query.remark}, '%')
            AND store_id = #{query.storeId}
            AND table_id = #{query.tableId}
            AND table_type_id = #{query.tableTypeId}
            AND member_id = #{query.memberId}
            AND persons = #{query.persons}
            AND status = #{query.status}
            AND create_time >= CONCAT(#{query.searchBeginTime}, ' 00:00:00')
            AND create_time <= CONCAT(#{query.searchEndTime}, ' 23:59:59')

        ORDER BY id DESC

