store_id = #{storeId}, table_id = #{tableId}, table_type_id = #{tableTypeId}, member_id = #{memberId}, contact_name = #{contactName}, contact_phone = #{contactPhone}, reservation_date = #{reservationDate}, reservation_time = #{reservationTime}, persons = #{persons}, remark = #{remark}, status = #{status}, confirm_time = #{confirmTime}, complete_time = #{completeTime}, create_time = #{createTime}, update_time = #{updateTime},
WHERE id = #{id}
